/// <summary>
/// AVA/WEN/2025/05/08  AVA_012816_CopyQuotation_CopyMatrix
/// </summary>
/// <param name = "_quotationId">SalesQuotationId</param>
/// <param name = "_forupdate">boolean</param>
/// <returns>AVASalesQuotationHasLines</returns>
static public AVASalesQuotationHasLines find(SalesQuotationId _quotationId, boolean _forupdate = false)
{
    AVASalesQuotationHasLines sqHasLines;

    if (_quotationId)
    {
        if (_forupdate)
        {
            sqHasLines.selectForUpdate(true);
        }

        select firstonly sqHasLines where sqHasLines.SalesQuotationId == _quotationId;
    }
    return sqHasLines;

}

/// <summary>
/// AVA/WEN/2025/05/08  AVA_012816_CopyQuotation_CopyMatrix
/// </summary>
/// <param name = "_quotationId">SalesQuotationId</param>
/// <returns>boolean</returns>
static boolean exist(SalesQuotationId _quotationId)
{
    return _quotationId && (select firstonly RecId from AVASalesQuotationHasLines
                                where AVASalesQuotationHasLines.salesquotationid == _quotationId).RecId != 0;
}
